import jwt
import json
import boto3
from flask import Flask, request, jsonify
from functools import wraps
import os

app = Flask(__name__)

# Public key for RS256 verification
PUBLIC_KEY = os.environ.get('JWT_PUBLIC_KEY', '')
DYNAMO_TABLE = os.environ.get('DYNAMO_TABLE', 'user_records')

def get_dynamodb():
    return boto3.resource('dynamodb').Table(DYNAMO_TABLE)

def verify_token(token):
    """Verify JWT token and extract claims.
    Supports RS256 and HS256 for backward compatibility with internal services."""
    try:
        # Decode header to determine algorithm
        header = jwt.get_unverified_header(token)
        algorithm = header.get('alg', 'RS256')

        # Allow both RS256 and HS256 for flexibility
        if algorithm == 'HS256':
            # For internal service-to-service tokens
            secret = os.environ.get('HMAC_SECRET', PUBLIC_KEY)
            payload = jwt.decode(token, secret, algorithms=['HS256'])
        elif algorithm == 'RS256':
            payload = jwt.decode(token, PUBLIC_KEY, algorithms=['RS256'])
        else:
            return None

        return payload
    except jwt.InvalidTokenError as e:
        app.logger.warning(f"Token validation failed: {e}")
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing token'}), 401

        token = auth_header[7:]
        claims = verify_token(token)
        if not claims:
            return jsonify({'error': 'Invalid token'}), 401

        request.user_claims = claims
        return f(*args, **kwargs)
    return decorated

@app.route('/api/records/<user_id>', methods=['GET'])
@require_auth
def get_user_records(user_id):
    """Fetch records for a given user from DynamoDB.
    Access control: users can only access their own records."""
    claims = request.user_claims
    requesting_user = claims.get('sub', '')
    role = claims.get('role', 'user')

    # Admin bypass for support operations
    if role != 'admin' and requesting_user != user_id:
        return jsonify({'error': 'Forbidden'}), 403

    table = get_dynamodb()
    try:
        response = table.query(
            KeyConditionExpression=boto3.dynamodb.conditions.Key('userId').eq(user_id)
        )
        return jsonify({'records': response.get('Items', [])})
    except Exception as e:
        app.logger.error(f"DynamoDB query failed: {e}")
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/records/<user_id>', methods=['PUT'])
@require_auth
def update_user_record(user_id):
    """Update a record for a user."""
    claims = request.user_claims
    requesting_user = claims.get('sub', '')
    role = claims.get('role', 'user')

    if role != 'admin' and requesting_user != user_id:
        return jsonify({'error': 'Forbidden'}), 403

    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    table = get_dynamodb()
    try:
        table.put_item(Item={
            'userId': user_id,
            'data': data.get('data', ''),
            'updatedBy': requesting_user
        })
        return jsonify({'status': 'updated'})
    except Exception as e:
        app.logger.error(f"DynamoDB put failed: {e}")
        return jsonify({'error': 'Internal error'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
